mapper.select:
select bo.id, bo.status, bo.operator, bo.operator_id, bo.proposer, bo.proposer_id, bo.priority, bo.env, bo.reason, bo.source, bo.belong,
bo.return_count, bo.unhandle_reason, bo.open_count, bo.expect_solve_date,
bo.create_date, bo.modify_date,
bo.name bugName,
p.name projectName, p.status projectStatus,
pl.name productLineName,
bd.name bizDomainName
from bug_offline bo
left join project p on bo.project_id = p.id
join product_line pl on pl.id = bo.product_line_id
join biz_domain bd on pl.biz_domain_id = bd.id


        and bo.id  in

            #{item}



        and bo.name like concat('%',#{name},'%')


        and bo.status in

            #{item}



        and bo.operator_id in

            #{item}



        and bo.proposer_id in

            #{item}



        and bo.project_id in

            #{item}



        and bo.product_line_id in

            #{item}



        and bd.id in

            #{item}



        and bo.priority in

            #{item}



        and bo.env in

            #{item}



        and bo.reason in

            #{item}



        and bo.source in

            #{item}



        and bo.belong in

            #{item}



        and bo.create_date >= #{createDateLeft} and bo.create_date <= #{createDateRight}


        and bo.modify_date >= #{modifyDateLeft} and bo.modify_date <= #{modifyDateRight}


        and bo.return_count = #{returnCount}
        and bo.return_count > #{returnCount}
        and bo.return_count >= #{returnCount}
        and bo.return_count < #{returnCount}
        and bo.return_count <= #{returnCount}


        and bo.open_count = #{openCount}
        and bo.open_count > #{openCount}
        and bo.open_count >= #{openCount}
        and bo.open_count < #{openCount}
        and bo.open_count <= #{openCount}


        and bo.id IN (
        select p.main_id
        from person p
        where p.user_id = #{copier}
        and p.type = 50
        and p.is_deleted = false
        )


        and bo.is_deleted = false


        and bo.proposer like concat('%',#{proposerLike},'%')

select id, project_id, product_line_id, name, status, last_operator, last_operator_id, operator, operator_id, proposer, proposer_id, priority, env, reason, source, belong, frequency, `desc`, open_count, return_count, delay_handle_reason, unhandle_reason, is_deleted, create_man_id, create_man, create_date, modify_man_id, modify_man, modify_date from bug_offline
is_deleted = false
and (operator_id in
#{item}
or proposer_id in
#{item}
)

mapper.update:
update bug_offline
is_deleted=true, modify_man = #{modifyMan}, modify_man_id = #{modifyManId},
where id=#{bugOfflineId}
